{
  "terms": [
    {
      "id": "lifetime_income_stream_equivalent_of_the_total_benefits_accrued",
      "label": "lifetime income stream equivalent of the total benefits accrued",
      "aliases": [],
      "source_refs": ["F037"]
    }
  ],
  "extractions": [
    {
      "unit": "F002:F003",
      "unit_attributes": {
        "statement": "The administrator of an individual account plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title) must furnish a pension benefit statement at least once each calendar quarter to a participant or beneficiary who has the right to direct the investment of assets in his or her account under the plan.",
        "actor": "The administrator of an individual account plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "actor_quote": "The administrator of an individual account plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["section 1021(i)(8)(B) of this title"]
      }
    },
    {
      "unit": "F002:F004",
      "unit_attributes": {
        "statement": "The administrator of an individual account plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title) must furnish a pension benefit statement at least once each calendar year to a participant or beneficiary who has his or her own account under the plan but does not have the right to direct the investment of assets in that account.",
        "actor": "The administrator of an individual account plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "actor_quote": "The administrator of an individual account plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["section 1021(i)(8)(B) of this title"]
      }
    },
    {
      "unit": "F002:F005",
      "unit_attributes": {
        "statement": "The administrator of an individual account plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title) must furnish a pension benefit statement upon written request to a plan beneficiary not described in clause (i) or (ii) of 29 U.S.C. 1025(a)(1)(A).",
        "actor": "The administrator of an individual account plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "actor_quote": "The administrator of an individual account plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["section 1021(i)(8)(B) of this title", "clause (i) or (ii)"]
      }
    },
    {
      "unit": "F006:F007",
      "unit_attributes": {
        "statement": "The administrator of a defined benefit plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title) must furnish a pension benefit statement at least once every 3 years to each participant with a nonforfeitable accrued benefit and who is employed by the employer maintaining the plan at the time the statement is to be furnished.",
        "actor": "The administrator of a defined benefit plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "actor_quote": "The administrator of a defined benefit plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["section 1021(i)(8)(B) of this title"]
      }
    },
    {
      "unit": "F006:F008",
      "unit_attributes": {
        "statement": "The administrator of a defined benefit plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title) must furnish a pension benefit statement to a participant or beneficiary of the plan upon written request.",
        "actor": "The administrator of a defined benefit plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "actor_quote": "The administrator of a defined benefit plan (other than a one-participant retirement plan described in section 1021(i)(8)(B) of this title)",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["section 1021(i)(8)(B) of this title"]
      }
    },
    {
      "unit": "F009",
      "unit_attributes": {
        "statement": "Information furnished under 29 U.S.C. 1025(a)(1)(B)(i) to a participant may be based on reasonable estimates determined under regulations prescribed by the Secretary, in consultation with the Pension Benefit Guaranty Corporation.",
        "actor": null,
        "actor_quote": null,
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may",
        "references": ["clause (i)"]
      }
    },
    {
      "unit": "F012:F015",
      "unit_attributes": {
        "statement": "A pension benefit statement under paragraph (1) must indicate, on the basis of the latest available information, the total benefits accrued, and the nonforfeitable pension benefits, if any, which have accrued, or the earliest date on which benefits will become nonforfeitable.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["paragraph (1)"]
      }
    },
    {
      "unit": "F012:F017",
      "unit_attributes": {
        "statement": "A pension benefit statement under paragraph (1) must include an explanation of any permitted disparity under section 401(l) of title 26 or any floor-offset arrangement that may be applied in determining any accrued benefits described in clause (i).",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["paragraph (1)", "section 401(l) of title 26", "clause (i)"]
      }
    },
    {
      "unit": "F012:F018",
      "unit_attributes": {
        "statement": "A pension benefit statement under paragraph (1) must be written in a manner calculated to be understood by the average plan participant.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["paragraph (1)"]
      }
    },
    {
      "unit": "F012:F019",
      "unit_attributes": {
        "statement": "A pension benefit statement under paragraph (1) may be delivered in written, electronic, or other appropriate form to the extent such form is reasonably accessible to the participant or beneficiary.",
        "actor": null,
        "actor_quote": null,
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may",
        "references": ["paragraph (1)"]
      }
    },
    {
      "unit": "F020:F021",
      "unit_attributes": {
        "statement": "In the case of an individual account plan, any pension benefit statement under clause (i) or (ii) of paragraph (1)(A) must include the value of each investment to which assets in the individual account have been allocated, determined as of the most recent valuation date under the plan, including the value of any assets held in the form of employer securities, without regard to whether such securities were contributed by the plan sponsor or acquired at the direction of the plan or of the participant or beneficiary.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["clause (i) or (ii) of paragraph (1)(A)"]
      }
    },
    {
      "unit": "F020:F023",
      "unit_attributes": {
        "statement": "In the case of an individual account plan, any pension benefit statement under paragraph (1)(A)(i) must include an explanation of any limitations or restrictions on any right of the participant or beneficiary under the plan to direct an investment.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["clause (i) or (ii) of paragraph (1)(A)", "paragraph (1)(A)(i)"]
      }
    },
    {
      "unit": "F020:F024",
      "unit_attributes": {
        "statement": "In the case of an individual account plan, any pension benefit statement under paragraph (1)(A)(i) must include an explanation, written in a manner calculated to be understood by the average plan participant, of the importance, for the long-term retirement security of participants and beneficiaries, of a well-balanced and diversified investment portfolio, including a statement of the risk that holding more than 20 percent of a portfolio in the security of one entity (such as employer securities) may not be adequately diversified.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["clause (i) or (ii) of paragraph (1)(A)", "paragraph (1)(A)(i)"]
      }
    },
    {
      "unit": "F020:F025",
      "unit_attributes": {
        "statement": "In the case of an individual account plan, any pension benefit statement under paragraph (1)(A)(i) must include a notice directing the participant or beneficiary to the Internet website of the Department of Labor for sources of information on individual investing and diversification.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["clause (i) or (ii) of paragraph (1)(A)", "paragraph (1)(A)(i)"]
      }
    },
    {
      "unit": "F020:F027",
      "unit_attributes": {
        "statement": "In the case of an individual account plan, any pension benefit statement under clause (i) or (ii) of paragraph (1)(A) must include the lifetime income disclosure described in subparagraph (D)(i).",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["clause (i) or (ii) of paragraph (1)(A)", "subparagraph (D)(i)"]
      }
    },
    {
      "unit": "F028",
      "unit_attributes": {
        "statement": "In the case of pension benefit statements described in clause (i) of paragraph (1)(A), a lifetime income disclosure under clause (iii) of subparagraph (B) is required to be included in only one pension benefit statement during any one 12-month period.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall be required",
        "references": ["clause (i) of paragraph (1)(A)", "clause (iii) of this subparagraph"]
      }
    },
    {
      "unit": "F029:F031",
      "unit_attributes": {
        "statement": "The requirements of subparagraph (A)(i)(II) are met if, at least annually and in accordance with requirements of the Secretary, the plan either updates the information described in such paragraph which is provided in the pension benefit statement, or provides in a separate statement such information as is necessary to enable a participant or beneficiary to determine their nonforfeitable vested benefits.",
        "actor": "the plan",
        "actor_quote": "the plan",
        "kind": "statement",
        "modality": "not_stated",
        "references": ["subparagraph (A)(i)(II)"]
      }
    },
    {
      "unit": "F035",
      "unit_attributes": {
        "statement": "A lifetime income disclosure must set forth the lifetime income stream equivalent of the total benefits accrued with respect to the participant or beneficiary.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall"
      }
    },
    {
      "unit": "F037",
      "unit_attributes": {
        "defines_term": "lifetime_income_stream_equivalent_of_the_total_benefits_accrued",
        "statement": "For purposes of subparagraph (D), the lifetime income stream equivalent of the total benefits accrued means the amount of monthly payments the participant or beneficiary would receive if the total accrued benefits of such participant or beneficiary were used to provide lifetime income streams described in subclause (III), based on assumptions specified in rules prescribed by the Secretary.",
        "actor": null,
        "actor_quote": null,
        "kind": "definition",
        "modality": "not_stated",
        "references": ["subclause (III)"]
      }
    },
    {
      "unit": "F039",
      "unit_attributes": {
        "statement": "The lifetime income streams described in subclause (III) are a qualified joint and survivor annuity (as defined in section 1055(d) of this title), based on assumptions specified in rules prescribed by the Secretary, including the assumption that the participant or beneficiary has a spouse of equal age, and a single life annuity.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated",
        "references": ["subclause (III)", "section 1055(d) of this title"]
      }
    },
    {
      "unit": "F039",
      "unit_attributes": {
        "statement": "The lifetime income streams described in subclause (III) may have a term certain or other features to the extent permitted under rules prescribed by the Secretary.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may",
        "references": ["subclause (III)"]
      }
    },
    {
      "unit": "F041:F045",
      "unit_attributes": {
        "statement": "Not later than 1 year after December 20, 2019, the Secretary must issue a model lifetime income disclosure, written in a manner so as to be understood by the average plan participant, which explains that the lifetime income stream equivalent is only provided as an illustration; explains that the actual payments under the lifetime income stream described in clause (i)(III) which may be purchased with the total benefits accrued will depend on numerous factors and may vary substantially from the lifetime income stream equivalent in the disclosures; explains the assumptions upon which the lifetime income stream equivalent was determined; and provides such other similar explanations as the Secretary considers appropriate.",
        "actor": "the Secretary",
        "actor_quote": "the Secretary",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["clause (i)(III)"]
      }
    },
    {
      "unit": "F047:F049",
      "unit_attributes": {
        "statement": "Not later than 1 year after December 20, 2019, the Secretary must prescribe assumptions which administrators of individual account plans may use in converting total accrued benefits into lifetime income stream equivalents for purposes of subparagraph (D), and issue interim final rules under clause (i).",
        "actor": "the Secretary",
        "actor_quote": "the Secretary",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["clause (i)"]
      }
    },
    {
      "unit": "F051",
      "unit_attributes": {
        "statement": "In prescribing assumptions under subclause (I), the Secretary may prescribe a single set of specific assumptions (in which case the Secretary may issue tables or factors which facilitate such conversions), or ranges of permissible assumptions.",
        "actor": "the Secretary",
        "actor_quote": "the Secretary",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may",
        "references": ["subclause (I)"]
      }
    },
    {
      "unit": "F051",
      "unit_attributes": {
        "statement": "To the extent that an accrued benefit is or may be invested in a lifetime income stream described in clause (i)(III), the assumptions prescribed under subclause (I) must, to the extent appropriate, permit administrators of individual account plans to use the amounts payable under such lifetime income stream as a lifetime income stream equivalent.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall",
        "references": ["clause (i)(III)", "subclause (I)"]
      }
    },
    {
      "unit": "F053",
      "unit_attributes": {
        "statement": "No plan fiduciary, plan sponsor, or other person shall have any liability under this subchapter solely by reason of the provision of lifetime income stream equivalents which are derived in accordance with the assumptions and rules described in clause (iii) and which include the explanations contained in the model lifetime income disclosure described in clause (ii), applying without regard to whether the provision of such lifetime income stream equivalent is required by subparagraph (B)(iii).",
        "actor": null,
        "actor_quote": null,
        "kind": "exemption",
        "modality": "not_required",
        "modality_quote": "No",
        "references": ["clause (iii)", "clause (ii)", "subparagraph (B)(iii)"]
      }
    },
    {
      "unit": "F055:F058",
      "unit_attributes": {
        "statement": "The requirement in subparagraph (B)(iii) applies to pension benefit statements furnished more than 12 months after the latest of the issuance by the Secretary of interim final rules under clause (i), the model disclosure under clause (ii), or the assumptions under clause (iii).",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall apply",
        "references": ["subparagraph (B)(iii)", "clause (i)", "clause (ii)", "clause (iii)"]
      }
    },
    {
      "unit": "F063",
      "unit_attributes": {
        "statement": "In the case of a defined benefit plan, the requirements of paragraph (1)(B)(i) must be treated as met with respect to a participant if at least once each year the administrator provides to the participant notice of the availability of the pension benefit statement and the ways in which the participant may obtain such statement.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "shall be treated as met",
        "references": ["paragraph (1)(B)(i)"]
      }
    },
    {
      "unit": "F063",
      "unit_attributes": {
        "statement": "In the case of a defined benefit plan, notice of the availability of the pension benefit statement and the ways in which the participant may obtain such statement may be delivered in written, electronic, or other appropriate form to the extent such form is reasonably accessible to the participant.",
        "actor": null,
        "actor_quote": null,
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may"
      }
    },
    {
      "unit": "F065",
      "unit_attributes": {
        "statement": "The Secretary may provide that years in which no employee or former employee benefits (within the meaning of section 410(b) of title 26) under the plan need not be taken into account in determining the 3-year period under paragraph (1)(B)(i).",
        "actor": "The Secretary",
        "actor_quote": "The Secretary",
        "kind": "authority",
        "modality": "may",
        "modality_quote": "may",
        "references": ["section 410(b) of title 26", "paragraph (1)(B)(i)"]
      }
    }
  ]
}
